import { createHash } from "node:crypto"
import { getPublicOriginFromRequest } from "@chatbotx.io/utils"
import "@/polyfill"
import { getTenantSettings } from "@/features/tenant/utils"
import baseSpec from "@/generated/public-spec.base.json"

// The document is derived from the committed base spec (generated by
// `pnpm --filter builder gen:public-spec`, drift-guarded by
// __tests__/public-spec-snapshot.test.ts) — this route must NOT import
// `publicRouter`, or Turbopack compiles the whole codebase for it. Only
// (tenant name, origin, filter) vary per request, so the result is cached
// in-process keyed by those three for TTL_SECONDS.
const TTL_SECONDS = 300
type CachedSpec = { body: string; etag: string; cachedAtMs: number }
const specCache = new Map<string, CachedSpec>()

function buildCacheKey(props: {
  tenantName: string
  origin: string
  filter: string | null
}): string {
  return `${props.tenantName}::${props.origin}::${props.filter ?? ""}`
}

function computeEtag(body: string): string {
  return `"${createHash("sha1").update(body).digest("hex")}"`
}

function buildSpecDocument(props: {
  origin: string
  filter: string | null
  tenantName: string
}): string {
  const paths = props.filter
    ? Object.fromEntries(
        Object.entries(baseSpec.paths).filter(([path]) =>
          path.startsWith(`/v1/${props.filter}`),
        ),
      )
    : baseSpec.paths

  return JSON.stringify({
    ...baseSpec,
    info: { ...baseSpec.info, title: props.tenantName },
    servers: [{ url: new URL("/api", props.origin).toString() }],
    paths,
  })
}

async function resolveCachedSpec(props: {
  origin: string
  filter: string | null
}): Promise<CachedSpec> {
  const { name: tenantName } = await getTenantSettings()
  const cacheKey = buildCacheKey({
    tenantName,
    origin: props.origin,
    filter: props.filter,
  })

  const cached = specCache.get(cacheKey)
  const now = Date.now()
  if (cached && now - cached.cachedAtMs < TTL_SECONDS * 1000) {
    return cached
  }

  const body = buildSpecDocument({
    origin: props.origin,
    filter: props.filter,
    tenantName,
  })

  const entry: CachedSpec = { body, etag: computeEtag(body), cachedAtMs: now }
  specCache.set(cacheKey, entry)
  return entry
}

async function handleRequest(request: Request) {
  const origin = getPublicOriginFromRequest(request)
  const filter = new URL(request.url).searchParams.get("filter")

  const cached = await resolveCachedSpec({ origin, filter })

  const ifNoneMatch = request.headers.get("If-None-Match")
  if (ifNoneMatch === cached.etag) {
    return new Response(null, {
      status: 304,
      headers: {
        ETag: cached.etag,
        "Cache-Control": `public, max-age=${TTL_SECONDS}, stale-while-revalidate=3600`,
      },
    })
  }

  return new Response(cached.body, {
    headers: {
      "Content-Type": "application/json",
      ETag: cached.etag,
      "Cache-Control": `public, max-age=${TTL_SECONDS}, stale-while-revalidate=3600`,
    },
  })
}

export const HEAD = handleRequest
export const GET = handleRequest
